  -- TASK_SHOOT_AT_ENTITY (0x08DA95E8298AE772)
  methods.taskShootAtEntity = function(self, target, duration, firingPattern)
    if type(target) == "table" then target = target.handle end
    if math_type(duration) == "float" then duration = math_tointeger((math_modf(duration))) or 0 end
    local t_firingPattern = type(firingPattern)
    if t_firingPattern == "string" then firingPattern = GetHashKey(firingPattern) elseif t_firingPattern == "table" then firingPattern = firingPattern.handle end
    TaskShootAtEntity(self.handle, target, duration, firingPattern)
    return self
  end
end

