  statics.wouldBeOccluded = function(entityModelHash, coords, p4)
    local t_entityModelHash = type(entityModelHash)
    if t_entityModelHash == "string" then entityModelHash = GetHashKey(entityModelHash) elseif t_entityModelHash == "table" then entityModelHash = entityModelHash.handle end
    local r0 = WouldEntityBeOccluded(entityModelHash, coords.x, coords.y, coords.z, p4)
    return (r0 ~= false and r0 ~= 0 and r0 ~= nil)
  end
