-- handwritten: runtime/client/mixins/Entity.lua

do

local DoesEntityExist, GetEntityType = DoesEntityExist, GetEntityType
local NetworkGetEntityIsNetworked, NetworkGetNetworkIdFromEntity = NetworkGetEntityIsNetworked, NetworkGetNetworkIdFromEntity
local SetModelAsNoLongerNeeded, HasModelLoaded, RequestModel = SetModelAsNoLongerNeeded, HasModelLoaded, RequestModel
local InvokeNative = Citizen.InvokeNative
local P = fx.Promise
local newError = P._internal.newError
local setmetatable, type, tostring, error = setmetatable, type, tostring, error

-- members usable even when the entity no longer exists (debug mode)
T.safe = { exists = true, handle = true, readyAsync = true, states = true, state = true }

---@param self fx.Entity
---@return boolean
getters.exists = function(self)
  local r = DoesEntityExist(self.handle)
  return r ~= false and r ~= 0 and r ~= nil
end

-- the bag name changes when the entity gets its network id (localEntity:<h> -> entity:<netId>)
---@type table<fx.Entity, fx.StateBag>
local statesCache = setmetatable({}, { __mode = "k" })
---@param self fx.Entity
---@return fx.StateBag
getters.states = function(self)
  local s = statesCache[self]
  if s ~= nil and rt.states.bagOf(s) == rt.states.entityBagName(self.handle) then return s end
  s = rt.states.entity(self)
  statesCache[self] = s
  return s
end
getters.state = getters.states

-- a freshly created networked entity may not have its network id yet
---@param self fx.Entity
---@param timeoutMs? integer
---@return fx.Promise<fx.Entity>
methods.readyAsync = function(self, timeoutMs)
  local h = self.handle
  local wantNet = rt.netIntent[self]
  return rt.waitUntil(tostring(self) .. ":readyAsync", function()
    if not DoesEntityExist(h) then return false end
    if wantNet or NetworkGetEntityIsNetworked(h) then
      return NetworkGetEntityIsNetworked(h) and NetworkGetNetworkIdFromEntity(h) ~= 0
    end
    return true
  end, timeoutMs, self)
end

-- Network control: the owner may refuse or lag, so the request is repeated until granted.
local NetworkRequestControlOfEntity, NetworkHasControlOfEntity = NetworkRequestControlOfEntity, NetworkHasControlOfEntity
local RequestCollisionAtCoord, HasCollisionLoadedAroundEntity, GetEntityCoords =
  RequestCollisionAtCoord, HasCollisionLoadedAroundEntity, GetEntityCoords

---@param self fx.Entity
---@param what string Method name, for the message
---@return fun() raise
local function gone(self, what)
  return function() error(newError("Error", ("%s:%s: the entity no longer exists"):format(tostring(self), what)), 0) end
end

---@param self fx.Entity
---@param timeoutMs? integer
---@return fx.Promise<fx.Entity>
methods.takeControlAsync = function(self, timeoutMs)
  local h = self.handle
  if not NetworkGetEntityIsNetworked(h) or NetworkHasControlOfEntity(h) then return P.resolve(self) end
  local lost = false
  return rt.waitUntil(tostring(self) .. ":takeControlAsync", function()
    if not DoesEntityExist(h) then lost = true; return true end
    if NetworkHasControlOfEntity(h) then return true end
    NetworkRequestControlOfEntity(h)
    return false
  end, timeoutMs):next(function()
    if lost then gone(self, "takeControlAsync")() end
    return self
  end)
end

---@param self fx.Entity
---@param timeoutMs? integer
---@return fx.Promise<fx.Entity>
methods.loadCollisionAsync = function(self, timeoutMs)
  local h = self.handle
  local lost = false
  return rt.waitUntil(tostring(self) .. ":loadCollisionAsync", function()
    if not DoesEntityExist(h) then lost = true; return true end
    if HasCollisionLoadedAroundEntity(h) then return true end
    local c = GetEntityCoords(h, false)
    RequestCollisionAtCoord(c.x, c.y, c.z)
    return false
  end, timeoutMs):next(function()
    if lost then gone(self, "loadCollisionAsync")() end
    return self
  end)
end

---@param self fx.Entity
---@param hash integer
---@param ... any
---@return any ...
methods.invoke = function(self, hash, ...)
  return InvokeNative(hash, self.handle, ...)
end

-- Entity(h) returns the wrapper of the real type
---@type (fun(h: integer): fx.Entity?)[] By GetEntityType value
local byType = { rt.lazyWrap("Ped"), rt.lazyWrap("Vehicle"), rt.lazyWrap("Object") }
local cache, mt = rt.entityCache, T.mt
---@param h fx.Entity|integer|nil
---@return fx.Entity?
T.wrap = function(h)
  if h == nil or h == 0 then return nil end
  if type(h) == "table" then return h end
  ---@cast h integer
  local w = byType[GetEntityType(h)]
  if w then return w(h) end
  local o = cache[h]
  if o ~= nil then return o end
  o = setmetatable({ handle = h }, mt)
  cache[h] = o
  return o
end

local DEFAULT_TIMEOUT = rt.DEFAULT_TIMEOUT

---@param label string
---@param hash integer
---@param timeoutMs? integer
---@return fx.Promise
function rt.loadModel(label, hash, timeoutMs)
  return rt.load(label, "model", RequestModel, HasModelLoaded, nil, timeoutMs, hash)
end

--- Promise version of a createRaw.
---@param label string
---@param isValid fun(hash: integer): boolean
---@param raw fx.RawCreate
---@param load? fx.ModelLoader Default rt.loadModel
---@return fx.CreateAsync
function rt.makeCreate(label, isValid, raw, load)
  load = load or rt.loadModel
  return function(model, ...)
    local hash = rt.hash(model)
    if type(hash) ~= "number" or not isValid(hash) then
      return P.reject(newError("Error", ("%s: invalid model '%s'"):format(label, tostring(model))))
    end
    local args = table.pack(...)
    local options = args[args.n]
    local timeout = type(options) == "table" and options.timeout or DEFAULT_TIMEOUT
    return load(label, hash, timeout):next(function()
      local e = raw(hash, table.unpack(args, 1, args.n))
      SetModelAsNoLongerNeeded(hash)
      if not e then error(label .. ": creation failed (native returned 0)", 0) end
      return e:readyAsync(timeout):next(nil, function(err)
        -- nobody holds the wrapper: an entity left behind could never be deleted
        if DoesEntityExist(e.handle) then DeleteEntity(e.handle) end
        rt.forget(e)
        return P.reject(err)
      end)
    end)
  end
end

--- Before a createRaw: raises in debug mode when the model is not loaded.
---@param label string
---@param hash integer
---@param model fx.Model|integer|string As given by the caller, for the error message
---@param isLoaded? fun(hash: integer): boolean Default HasModelLoaded
---@return boolean
function rt.requireLoaded(label, hash, model, isLoaded)
  if (isLoaded or HasModelLoaded)(hash) then return true end
  if fx.debug then
    error(("%s: model '%s' is not loaded (use the Promise version, or load it first)"):format(label, tostring(model)), 3)
  end
  return false
end

---@param position vector3|vector4
---@param heading? number Default: the w of a vector4, else 0.0
---@return number
function rt.heading(position, heading)
  -- always a float: an integer reaches a float parameter as raw bits
  if heading ~= nil then return heading + 0.0 end
  if type(position) == "vector4" then return position.w + 0.0 end
  return 0.0
end

local FreezeEntityPosition, SetEntityCoordsNoOffset, SetEntityHeading =
  FreezeEntityPosition, SetEntityCoordsNoOffset, SetEntityHeading

---@param self fx.Entity
---@param position vector3|vector4
---@param options? fx.TeleportOptions
---@return fx.Promise
methods.teleportAsync = function(self, position, options)
  local h = self.handle
  local x, y, z = position.x + 0.0, position.y + 0.0, position.z + 0.0
  local timeout = options and options.timeout
  local heading = options and options.heading or (type(position) == "vector4" and position.w or nil)
  -- frozen while the collision loads: the entity would fall through the map
  FreezeEntityPosition(h, true)
  SetEntityCoordsNoOffset(h, x, y, z, false, false, false)
  ---@return fx.Promise?
  local function toGround()
    if not (options and options.ground) then return nil end
    return fx.Game.getGroundZAsync(vector3(x, y, z), timeout):next(function(gz)
      SetEntityCoordsNoOffset(h, x, y, gz, false, false, false)
    end)
  end
  return methods.loadCollisionAsync(self, timeout):next(toGround):next(function()
    if heading then SetEntityHeading(h, heading + 0.0) end
    FreezeEntityPosition(h, false)
    return self
  end, function(err)
    FreezeEntityPosition(h, false)
    return P.reject(err)
  end)
end

end

return rt.finalize(T)
